    'portfolio_instagram_manager_title' => 'Instagram manager',
    'portfolio_kbdny_content' => '<h3>Project Overview</h3> <p>The Kbdny (Abdny) Dropshipping & Affiliate E-Commerce Platform is a robust, enterprise-grade multi-vendor ecosystem designed to bridge the gap between product suppliers (Vendors) and marketers (Affiliates). Built on Laravel and optimized for high-volume transactions, it provides an end-to-end operational backend for managing dropshipping logistics, dynamic commissions, and complex fulfillment.</p> <h3>Key Features</h3> <ul> <li><strong>Multi-Role Architecture:</strong> A structured system powers separating operations between the system (Moderators), and End Customers.</li> <li><strong>Advanced Inventory & SKU Management:</strong> Dynamic SKU generation, multi-variant tracking, auto-syncing stock levels across vendors, and sophisticated tools for product pricing and approval workflows.</li> <li><strong>Affiliate Operations & Commissions:</strong> Dedicated affiliate portals where marketers can create API keys, track real-times, manage their custom shopping carts, and oversee payouts.</li> <li><strong>Logistics & Request Fulfillment:</strong> Comprehensive tools for request states including Partial Delivery, Returning, and Replacing. It integrates seamlessly with external shipping companies using bulk Excel exports (R2S, Sheet2) for rapid processing.</li> <li><strong>Financial Tracking:</strong> An integrated wallet and payment request system handling dynamic payouts, balance adjustments, and platform fees.</li> </ul> <h3>Technical Highlights</h3> <p>Developed with modern PHP practices on the Laravel framework, the application utilizes sophisticated queue functions for bulk request processing, advanced database relationships for multi-level commission distribution, and secure APIs for external affiliate integrations. The UI ensures operational speed through bulk editing capabilities and real-time state tracking.</p>',
    'portfolio_kbdny_desc' => 'A comprehensive enterprise-grade dropshipping and affiliate ecosystem. Features advanced multi-role access (Vendors, Affiliates, Moderators), automated inventory & SKU management, robust order fulfillment with bulk Excel processing, dynamic commission tracking, and complex logistics handling including returns, partial deliveries, and wallet payouts.',
    'portfolio_kbdny_title' => 'Kbdny E-Commerce & Affiliate Platform',
